import java.util.*;class Customer{private final String name;public Customer(String n){if(n==null||n.trim().isEmpty())throw new IllegalArgumentException();name=n;}public String getName(){return name;}}
interface Seat{String getId();double getPrice();}class RegularSeat implements Seat{private final String id;public RegularSeat(String i){id=valid(i);}public String getId(){return id;}public double getPrice(){return 150;}private static String valid(String x){if(x==null||x.trim().isEmpty())throw new IllegalArgumentException();return x;}}
class PremiumSeat implements Seat{private final String id;public PremiumSeat(String i){id=valid(i);}public String getId(){return id;}public double getPrice(){return 250;}private static String valid(String x){if(x==null||x.trim().isEmpty())throw new IllegalArgumentException();return x;}}
class ReclinerSeat implements Seat{private final String id;public ReclinerSeat(String i){id=valid(i);}public String getId(){return id;}public double getPrice(){return 400;}private static String valid(String x){if(x==null||x.trim().isEmpty())throw new IllegalArgumentException();return x;}}
class Show{private final String id,time;private final Set<String> booked=new HashSet<>();public Show(String i,String t){if(i==null||i.trim().isEmpty()||t==null||t.trim().isEmpty())throw new IllegalArgumentException();id=i;time=t;}public boolean isSeatAvailable(Seat s){return s!=null&&!booked.contains(s.getId());}boolean reserve(Seat s){return s!=null&&booked.add(s.getId());}void release(Seat s){if(s!=null)booked.remove(s.getId());}}
class Booking{private final Customer customer;private final Show show;private final List<Seat> seats;private boolean cancelled;Booking(Customer c,Show s,List<Seat> x){customer=c;show=s;seats=new ArrayList<>(x);}public double getTotal(){double n=0;for(Seat s:seats)n+=s.getPrice();return n;}public List<Seat> getSeats(){return Collections.unmodifiableList(seats);}public boolean isCancelled(){return cancelled;}void cancel(){if(cancelled)return;for(Seat s:seats)show.release(s);cancelled=true;}}
public class TicketCounter{public static Booking book(Customer c,Show s,List<Seat> seats){if(c==null||s==null||seats==null||seats.isEmpty()||seats.size()>6)throw new IllegalArgumentException();Set<String> ids=new HashSet<>();for(Seat x:seats)if(x==null||!ids.add(x.getId())||!s.isSeatAvailable(x))throw new IllegalStateException("Seat unavailable or duplicate");for(Seat x:seats)s.reserve(x);return new Booking(c,s,seats);}public static void cancel(Booking b,boolean started){if(b==null)throw new IllegalArgumentException();if(started)throw new IllegalStateException("Cannot cancel after the show starts");b.cancel();}}
